// ─── NAVIGATION ──────────────────────────────────────────────────────────────
function goPage(id){ nav(null,id); }
function nav(el,id){
  var overviewRoute={ 'doc-select':'dataset', 'data-map':'map', 'planning-flow':'flow', 'ct388-check':'check' };
  if(overviewRoute[id]){ OVERVIEW_ACTIVE_TAB=overviewRoute[id]; id='overview-ct388'; }
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('on'));
  var pg=document.getElementById('p-'+id);
  if(pg) pg.classList.add('on');
  CUR_PAGE=id;
  document.querySelectorAll('.nav-a').forEach(n=>n.classList.remove('on'));
  if(el) el.classList.add('on');
  else{
    document.querySelectorAll('.nav-a').forEach(n=>{
      if(n.getAttribute('onclick')&&n.getAttribute('onclick').includes("'"+id+"'")) n.classList.add('on');
    });
  }
  if(id==='tracker') loadChildren().then(function(){ applyChildrenToTracker(); renderTracker(); });
  if(id==='calendar') renderCalendar();
  if(id==='builder') renderBuilder();
  renderNurseryByPage(id);
  renderKindergartenByPage(id);
  if(id==='plan-from-data') renderPlanWizard();
  if(id==='observation-log') loadChildren().then(renderObservationJournal);
  if(id==='child-profile') loadChildren().then(renderChildProfile);
  if(id==='portfolio') loadChildren().then(renderPortfolio);
  if(id==='parent-sheet') renderParentCommunication();
  if(id==='dashboard') renderDashboard();
  if(id==='data-admin') renderDataAdmin();
  if(id==='overview-ct388') renderOverviewHub();
  if(id==='settings') renderSettings();
  if(id==='home') renderHomeDashboard();
  if(id==='superadmin') loadSuperadminSchools(SUPERADMIN_TAB);
}

function setAge(a,el){
  var dataAge=(a==='nt12'||a==='nt24')?'nt':a;
  AGE=dataAge;
  document.querySelectorAll('.ap').forEach(p=>p.classList.remove('on'));
  if(el) el.classList.add('on');
  renderKH();
renderKhPhases();
  var lbl={nt:'Nhà trẻ 12-36T',nt12:'Nhà trẻ 12-24T',nt24:'Nhà trẻ 24-36T',mg3:'MG Bé 3-4T',mg4:'MG Nhỡ 4-5T',mg5:'MG Lớn 5-6T'};
  var kl=document.getElementById('kh-lbl'); if(kl) kl.textContent=lbl[a]||lbl[dataAge];
  var tl2=document.getElementById('tracker-age'); if(tl2) tl2.textContent=lbl[a]||lbl[dataAge];
  var b1=document.getElementById('bld-themes');
  if(b1){delete b1.dataset.done;b1.innerHTML='';}
  var b2=document.getElementById('bld-acts');if(b2)b2.innerHTML='';
  var b3=document.getElementById('bld-result');if(b3)b3.innerHTML='';
  PICKED_THEME='T9';PICKED_ACTS={};
  if(CUR_PAGE==='tracker')renderTracker();
  if(CUR_PAGE==='builder')renderBuilder();
  if(CUR_PAGE==='calendar')renderCalendar();
  toast('Đã chọn: '+(lbl[a]||lbl[dataAge]));
}

function ctTab(btn,id){
  btn.closest('.tabs').querySelectorAll('.tab').forEach(t=>t.classList.remove('on'));
  btn.classList.add('on');
  ['ct-pc','ct-nl','ct-lv','ct-ss'].forEach(k=>{
    var el=document.getElementById(k);
    if(el) el.style.display=k===id?'':'none';
  });
  if(id==='ct-nl'&&!document.getElementById('ct-nl').dataset.done) renderCTNL();
  if(id==='ct-lv'&&!document.getElementById('ct-lv').dataset.done) renderCTLV();
  if(id==='ct-ss'&&!document.getElementById('ct-ss').dataset.done) renderCTSS();
}

function steamTab(btn,filter){
  btn.closest('.tabs').querySelectorAll('.tab').forEach(t=>t.classList.remove('on'));
  btn.classList.add('on');
  renderSteam(filter);
}

function toggleSearch(){
  var box=document.getElementById('srch-box');
  box.style.display=box.style.display==='none'?'block':'none';
  document.getElementById('btn-search').classList.toggle('active');
  if(box.style.display==='block') document.getElementById('srch-in').focus();
}

function doSearch(q){
  if(!q.trim()) return;
  var results=[];
  THEMES[AGE].forEach(t=>{
    if((t[1]+t[2]).toLowerCase().includes(q.toLowerCase()))
      results.push({page:'kh',label:'KH năm: '+t[1],sub:t[2]});
  });
  NLS.forEach(n=>{
    if((n.t+n.d).toLowerCase().includes(q.toLowerCase()))
      results.push({page:'nl',label:'Năng lực: '+n.t,sub:n.d.slice(0,60)+'...'});
  });
  LESSONS.forEach(l=>{
    if(l.t.toLowerCase().includes(q.toLowerCase()))
      results.push({page:'baihoc',label:'Bài học: '+l.t.slice(0,50),sub:l.sub});
  });
  var bodyHtml=results.length
    ? '<div id="search-results">'+results.map((r,i)=>`<div data-res-idx="${i}" style="padding:10px 0;border-bottom:1px solid var(--border);cursor:pointer;transition:.12s" onmouseover="this.style.background='+"'var(--pk-lt)'"+" onmouseout="this.style.background=''">
        <div style="font-size:13px;font-weight:700;color:var(--pu)">${r.label}</div>
        <div style="font-size:11.5px;color:var(--muted)">${r.sub}</div>
      </div>`).join('')+'</div>'
    : '<div style="padding:20px;text-align:center;color:var(--muted)">Không tìm thấy kết quả phù hợp</div>';
  openModal('Kết quả tìm kiếm: "'+q+'"', bodyHtml);
  // Attach listeners after modal renders
  setTimeout(function(){
    var wrap=document.getElementById('search-results');
    if(!wrap) return;
    wrap.querySelectorAll('[data-res-idx]').forEach(function(row){
      row.addEventListener('click',function(){
        goPage(results[+this.dataset.resIdx].page);
        closeModalBtn();
      });
    });
  },50);
}

// ─── MODAL ────────────────────────────────────────────────────────────────────
function openModal(title, body){
  document.getElementById('modal-title').textContent=title;
  document.getElementById('modal-body').innerHTML=body;
  document.getElementById('modal-bg').classList.add('open');
}
function closeModal(e){ if(e.target.id==='modal-bg') closeModalBtn(); }
function closeModalBtn(){ document.getElementById('modal-bg').classList.remove('open'); }

// ─── TOAST ────────────────────────────────────────────────────────────────────
function toast(msg){
  var t=document.getElementById('toast');
  t.textContent=msg; t.classList.add('show');
  setTimeout(()=>t.classList.remove('show'),2500);
}

