function renderWeek(){
  var el=document.getElementById('wk-tbl'); if(!el) return;
  var days=['Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6'];
  var h='<thead><tr><th style="width:90px">Hoạt động</th>'+days.map(d=>`<th>${d}</th>`).join('')+'</tr></thead><tbody>';
  WEEK_DATA.forEach(r=>{
    h+=`<tr><td class="rh" style="white-space:pre-line">${r.n}</td>`;
    r.d.forEach((cell,ci)=>{
      var bg=r.steam&&ci===1?' bg-st':r.sel?' bg-sl':'';
      var nlm=cell.match(/\[NL:[^\]]+\]/g)||[];
      var txt=cell.replace(/\[NL:[^\]]+\]/g,'');
      var nls=nlm.map(m=>`<span class="nl-tag">${m.slice(4,-1)}</span>`).join('');
      h+=`<td class="${bg}" style="white-space:pre-line">${txt}${nls?'<div>'+nls+'</div>':''}</td>`;
    });
    h+=`</tr>`;
  });
  h+='</tbody>';
  el.innerHTML=h;
}


