var KH_AGE_FILTER = 'all', KH_DOM_FILTER = 'all';

function khFilter(type, val){
  if(type==='age'){
    KH_AGE_FILTER = val;
    document.querySelectorAll('#kh-filter-age .kh-ft').forEach(b=>b.classList.remove('on'));
    document.querySelectorAll('#kh-filter-age .kh-ft').forEach(b=>{
      if(b.getAttribute('onclick').includes("'"+val+"'")) b.classList.add('on');
    });
  } else {
    KH_DOM_FILTER = val;
    document.querySelectorAll('#kh-filter-domain .kh-ft').forEach(b=>b.classList.remove('on'));
    document.querySelectorAll('#kh-filter-domain .kh-ft').forEach(b=>{
      if(b.getAttribute('onclick').includes("'"+val+"'")) b.classList.add('on');
    });
  }
  renderLessons();
}

