function renderTracker(){
  var el=document.getElementById('tracker-body'); if(!el) return;
  var nlLabels=['Giao tiếp','Hợp tác','GQVĐ','Thích ứng','Tự lực'];
  var h='<div style="overflow-x:auto"><div class="et-grid" style="margin-bottom:6px">'+
    '<div style="font-size:11px;font-weight:700;color:var(--muted)">Tên trẻ</div>'+
    nlLabels.map(n=>`<div style="text-align:center;font-size:10.5px;font-weight:700;color:var(--pu)">${n}</div>`).join('')+
    '</div>';
  TRACKER_STUDENTS.forEach((s,si)=>{
    if(!TRACKER_DATA[s]) TRACKER_DATA[s]={};
    h+=`<div class="et-grid" style="margin-bottom:5px">
      <div class="et-name">${s}</div>
      ${nlLabels.map((nl,ni)=>`<div class="et-cell">
        <div style="display:flex;gap:2px">
          <button class="lvl-btn lI ${TRACKER_DATA[s][nl]==='I'?'on':''}" data-si="${si}" data-ni="${ni}" data-lv="I">I</button>
          <button class="lvl-btn lH ${TRACKER_DATA[s][nl]==='H'?'on':''}" data-si="${si}" data-ni="${ni}" data-lv="H">H</button>
          <button class="lvl-btn lV ${TRACKER_DATA[s][nl]==='V'?'on':''}" data-si="${si}" data-ni="${ni}" data-lv="V">V</button>
        </div>
      </div>`).join('')}
    </div>`;
  });
  h+='</div>';
  el.innerHTML=h;
  // Event delegation – one listener on container
  el.addEventListener('click',function(e){
    var btn=e.target.closest('.lvl-btn');
    if(!btn) return;
    var s=TRACKER_STUDENTS[+btn.dataset.si];
    var nl=['Giao tiếp','Hợp tác','GQVĐ','Thích ứng','Tự lực'][+btn.dataset.ni];
    var lv=btn.dataset.lv;
    setLevel(s, nl, lv, btn);
  });
  renderTrackerStat();
}

function setLevel(student,nl,level,btn){if(!TRACKER_DATA[student])TRACKER_DATA[student]={};
  TRACKER_DATA[student][nl]=level;
  btn.closest('.et-cell').querySelectorAll('.lvl-btn').forEach(b=>{
    b.classList.remove('on');
    if(b.textContent===level) b.classList.add('on');
  });
  renderTrackerStat();
  toast('Đã ghi nhận: '+student+' – '+nl+' – '+level);
}

function renderTrackerStat(){
  var el=document.getElementById('tracker-stat'); if(!el) return;
  var nlLabels=['Giao tiếp','Hợp tác','GQVĐ','Thích ứng','Tự lực'];
  var n=TRACKER_STUDENTS.length;
  el.innerHTML=nlLabels.map(nl=>{
    var counts={I:0,H:0,V:0,x:0};
    TRACKER_STUDENTS.forEach(s=>{
      var v=TRACKER_DATA[s]&&TRACKER_DATA[s][nl];
      if(v) counts[v]++; else counts.x++;
    });
    var hv=counts.H+counts.V;
    var pct=Math.round(hv/n*100);
    return `<div style="margin-bottom:12px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px">
        <div style="font-size:12.5px;font-weight:700">${nl}</div>
        <div style="font-size:11px;color:var(--muted)">Đạt H/V: <strong style="color:var(--gn)">${hv}/${n} (${pct}%)</strong></div>
      </div>
      <div style="display:flex;gap:2px;height:10px;border-radius:5px;overflow:hidden">
        <div style="width:${counts.I/n*100}%;background:var(--ye);transition:.5s" title="I: ${counts.I}"></div>
        <div style="width:${counts.H/n*100}%;background:var(--bl);transition:.5s" title="H: ${counts.H}"></div>
        <div style="width:${counts.V/n*100}%;background:var(--gn);transition:.5s" title="V: ${counts.V}"></div>
        <div style="width:${counts.x/n*100}%;background:var(--border);transition:.5s" title="Chưa đánh giá: ${counts.x}"></div>
      </div>
      <div style="display:flex;gap:10px;margin-top:3px;font-size:10px;color:var(--muted)">
        <span style="color:var(--ye)">🟡 I:${counts.I}</span>
        <span style="color:var(--bl)">🔵 H:${counts.H}</span>
        <span style="color:var(--gn)">🟢 V:${counts.V}</span>
        <span>⬜ Chưa:${counts.x}</span>
      </div>
    </div>`;
  }).join('');
}

function exportTracker(){
  if(blockDownloadIfDisabled()) return;
  var nlLabels=['Giao tiếp','Hợp tác','GQVĐ','Thích ứng','Tự lực'];
  var rows=[['Tên trẻ',...nlLabels]];
  TRACKER_STUDENTS.forEach(s=>{
    rows.push([s,...nlLabels.map(nl=>(TRACKER_DATA[s]&&TRACKER_DATA[s][nl])||'')]);
  });
  var csv=rows.map(r=>r.join(',')).join('\n');
  var a=document.createElement('a');
  a.href='data:text/csv;charset=utf-8,\uFEFF'+encodeURIComponent(csv);
  a.download='DanhGia_NangLuc_'+new Date().toISOString().slice(0,10)+'.csv';
  a.click();
  toast('✅ Đã xuất file CSV!');
}


function addStudent(){
  var name=prompt('Nhập tên học sinh:','');
  if(!name||!name.trim()) return;
  name=name.trim();
  apiPost('/api/children',{full_name:name}).then(function(){
    return loadChildren();
  }).then(function(){
    applyChildrenToTracker();
    renderTracker();
    toast('✅ Đã thêm: '+name);
  }).catch(function(e){ toast('❌ Không thêm được: '+e.message); });
}

function applyChildrenToTracker(){
  if(CHILDREN_LIST.length){
    TRACKER_STUDENTS=CHILDREN_LIST.map(function(c){return c.full_name;});
  }
  TRACKER_STUDENTS.forEach(function(s){ if(!TRACKER_DATA[s]) TRACKER_DATA[s]={}; });
}

