    +_hnCard('📚','Điều chỉnh học liệu','Trực quan hơn · Học liệu cảm giác · Thẻ hình ảnh hỗ trợ giao tiếp','gn')
    +_hnCard('🏠','Điều chỉnh môi trường','Góc yên tĩnh riêng · Lối đi thông thoáng · Giảm kích thích quá mức','or')
    +'</div>'
    +'<div style="background:var(--pu-lt);border-radius:10px;padding:13px"><div style="font-weight:700;font-size:12px;color:var(--pu);margin-bottom:8px">🗂️ Nguyên tắc đánh giá trẻ hòa nhập</div>'
    +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:11.5px;line-height:1.7">'
    +'<div>✓ So sánh trẻ với <strong>chính trẻ</strong> ở giai đoạn trước<br>✓ Không so sánh với trẻ bình thường cùng lớp<br>✓ Ghi nhận mọi tiến bộ dù nhỏ</div>'
    +'<div>✓ Minh chứng: ảnh, video, ghi chú hành vi<br>✓ Phối hợp gia đình + chuyên gia tâm lý<br>✓ Hồ sơ giáo dục cá nhân (IEP)</div>'
    +'</div></div>'
