function renderSteam(filter){
  filter=filter||'st-all';
  var el=document.getElementById('steam-grid'); if(!el) return;
  var list=STEAM.filter(s=>{
    if(filter==='st-all') return true;
    if(filter==='st-steam') return s.tag==='STEAM';
    if(filter==='st-sel') return s.tag==='SEL';
    if(filter==='st-nhanthu') return s.lv==='nhanthu';
    if(filter==='st-xahoi') return s.lv==='xahoi';
    return true;
  });
  el.innerHTML=list.map(s=>`<div class="stc" style="background:${CClt[s.c]};border-color:var(--${s.c}-md)">
    <div class="stc-hdr">
      <span class="stc-em">${s.i}</span>
      <div><div class="stc-nm" style="color:${CC[s.c]}">${s.t}</div>
        <div class="stc-tags">
          <span class="stc-tag" style="color:${CC[s.c]}">${s.tag}</span>
          <span class="stc-tag" style="color:var(--muted)">${s.a}</span>
          <span class="stc-tag" style="color:var(--pu)">${s.ct}</span>
        </div>
      </div>
    </div>
    <div style="color:var(--muted)">${s.d}</div>
  </div>`).join('');
}

function renderCalendar(){
  var hdrEl=document.getElementById('cal-days-hdr');
  var gridEl=document.getElementById('cal-grid');
  var evEl=document.getElementById('cal-events');
  if(!hdrEl) return;
  var mths=['Tháng 9','Tháng 10','Tháng 11','Tháng 12','Tháng 1','Tháng 2','Tháng 3','Tháng 4','Tháng 5'];
  var yrMap=[2026,2026,2026,2026,2027,2027,2027,2027,2027];
  document.getElementById('cal-month').textContent=mths[CAL_MONTH]+'/'+yrMap[CAL_MONTH];
  var days=['CN','T2','T3','T4','T5','T6','T7'];
  hdrEl.innerHTML=days.map(d=>`<div class="cal-day">${d}</div>`).join('');
  // Build days
  var monthOffset=[8,9,10,11,0,1,2,3,4][CAL_MONTH];
  var year=yrMap[CAL_MONTH];
  var firstDay=new Date(year,monthOffset,1).getDay();
  var daysInMonth=new Date(year,monthOffset+1,0).getDate();
  var events=CAL_EVENTS[CAL_MONTH]||[];
  var evMap={};
  events.forEach(e=>{ evMap[e.d]=e; });
  var cells='';
  for(var i=0;i<firstDay;i++) cells+='<div></div>';
  for(var d=1;d<=daysInMonth;d++){
    var cls='cal-cell';
    var ev=evMap[d];
    if(ev) cls+=' has-ev';
    cells+=`<div class="${cls}" title="${ev?ev.t:''}" data-cal-day="${d}">${d}</div>`;
  }
  gridEl.innerHTML=cells;
  // Event delegation for calendar cells
  gridEl.addEventListener('click',function(e){
    var cell=e.target.closest('.has-ev');
    if(!cell) return;
    var day=+cell.dataset.calDay;
    var ev=evMap[day];
    if(!ev) return;
    openModal(ev.t,
      '<div class="note info"><i class="ti ti-calendar-event"></i><div>'+ev.t+'</div></div>'+
      '<div style="font-size:12px;color:var(--muted);margin-top:8px">Ngày '+day+'/'+
      (monthOffset+1)+'/'+year+' · '+mths[CAL_MONTH]+'/'+yrMap[CAL_MONTH]+'</div>');
  });
  evEl.innerHTML=events.map(e=>`<div style="display:flex;align-items:center;gap:9px;padding:8px 0;border-bottom:1px solid var(--border)">
    <div style="width:28px;height:28px;border-radius:7px;background:${CClt[e.c]};display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:${CC[e.c]};flex-shrink:0">${e.d}</div>
    <div style="font-size:12.5px;color:var(--text)">${e.t}</div>
  </div>`).join('');
}

window.calNav=function(dir){
  CAL_MONTH=Math.max(0,Math.min(8,CAL_MONTH+dir));
  renderCalendar();
};

function downloadFile(fn,n){
  if(blockDownloadIfDisabled()) return;
  var fd = FILE_DATA[fn];
  if(!fd){toast('❌ Không tìm thấy file: '+fn);return;}
  var byteStr = atob(fd.b64);
  var ab = new ArrayBuffer(byteStr.length);
  var ia = new Uint8Array(ab);
  for(var i=0;i<byteStr.length;i++) ia[i]=byteStr.charCodeAt(i);
  var blob = new Blob([ab],{type:fd.mime});
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href=url; a.download=fn;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url),1000);
  toast('⬇️ Đang tải: '+n);
}

function printDocFile(fn,n){
  // Dùng blob URL mở trong tab rồi gọi print
  var fd = FILE_DATA[fn];
  if(!fd){toast('❌ Không tìm thấy file');return;}
  var byteStr = atob(fd.b64);
  var ab = new ArrayBuffer(byteStr.length);
  var ia = new Uint8Array(ab);
  for(var i=0;i<byteStr.length;i++) ia[i]=byteStr.charCodeAt(i);
  var blob = new Blob([ab],{type:fd.mime});
  var url = URL.createObjectURL(blob);
  var w = window.open(url,'_blank');
  if(w){
    w.addEventListener('load',function(){try{w.print();}catch(e){}});
    toast('🖨️ Đang mở để in: '+n);
  } else {
    // fallback: tải về
    downloadFile(fn,n);
    toast('📥 Tải về để in: '+n);
  }
}

function previewFile(fn,n){
  var fd = FILE_DATA[fn];
  if(!fd){toast('❌ Không tìm thấy file');return;}
  var byteStr = atob(fd.b64);
  var ab = new ArrayBuffer(byteStr.length);
  var ia = new Uint8Array(ab);
  for(var i=0;i<byteStr.length;i++) ia[i]=byteStr.charCodeAt(i);
  var blob = new Blob([ab],{type:fd.mime});
  var url = URL.createObjectURL(blob);
  window.open(url,'_blank');
  toast('📂 Đang mở: '+n);
}
