var _donateAutoCloseTimer = null;
function clearDonateAutoClose(){
  if(_donateAutoCloseTimer){ clearTimeout(_donateAutoCloseTimer); _donateAutoCloseTimer = null; }
}

function toggleDonatePanel(){
  var panel = document.getElementById('tb-donate-panel');
  if(!panel) return;
  var btn = document.getElementById('btn-donate');
  if(btn) btn.classList.remove('attn');
  clearDonateAutoClose();
  if(panel.style.display === 'block'){ panel.style.display = 'none'; return; }
  panel.innerHTML = donatePanelContent();
  panel.style.display = 'block';
}
document.addEventListener('click', function(ev){
  var panel = document.getElementById('tb-donate-panel');
  var btn = document.getElementById('btn-donate');
  if(!panel || panel.style.display !== 'block') return;
  if(panel.contains(ev.target) || (btn && btn.contains(ev.target))) return;
  clearDonateAutoClose();
  panel.style.display = 'none';
});

// Thỉnh thoảng TỰ MỞ popup ủng hộ vài giây để dễ chú ý hơn (thay vì chỉ nhấp
// nháy icon) — tự đóng lại sau đó nếu người dùng không tương tác; di chuột
// vào thì giữ mở lâu hơn để có thời gian đọc/quét mã.
function pulseDonateAttention(){
  var btn = document.getElementById('btn-donate');
  var panel = document.getElementById('tb-donate-panel');
  if(!btn || !panel || panel.style.display === 'block') return;
  btn.classList.add('attn');
  setTimeout(function(){ btn.classList.remove('attn'); }, 3200);
  panel.innerHTML = donatePanelContent();
  panel.style.display = 'block';
  clearDonateAutoClose();
  _donateAutoCloseTimer = setTimeout(function(){ panel.style.display = 'none'; }, 8000);
  panel.onmouseenter = function(){ clearDonateAutoClose(); };
  panel.onmouseleave = function(){
    clearDonateAutoClose();
    _donateAutoCloseTimer = setTimeout(function(){ panel.style.display = 'none'; }, 3000);
  };
}



// ─── UPLOAD TÀI LIỆU ─────────────────────────────────────────────
var GA_UPLOADED_FILES = []; // [{name, size, type, b64, text}]

function handleFileSelect(files){ processFiles(Array.from(files)); }
function handleFileDrop(e){
  e.preventDefault();
  document.getElementById('ga-upload-zone').classList.remove('drag');
  processFiles(Array.from(e.dataTransfer.files));
}

async function processFiles(files){
  var allowed = ['pdf','docx','doc','txt','xlsx','xls'];
  for(var file of files){
    if(GA_UPLOADED_FILES.length >= 5){ toast('⚠️ Tối đa 5 file'); break; }
    if(file.size > 5*1024*1024){ toast('⚠️ File "'+file.name+'" quá 5MB, bỏ qua'); continue; }
    var ext = file.name.split('.').pop().toLowerCase();
    if(!allowed.includes(ext)){ toast('⚠️ Định dạng "'+ext+'" chưa hỗ trợ'); continue; }
    if(GA_UPLOADED_FILES.find(f=>f.name===file.name)){ toast('File này đã được thêm'); continue; }
    var b64 = await readFileB64(file);
    var text = '';
    if(ext==='txt'){ text = atob(b64); }
    GA_UPLOADED_FILES.push({ name:file.name, size:file.size, type:file.type, ext, b64, text });
    toast('✅ Đã thêm: '+file.name);
  }
  renderUploadedFiles();
}

function readFileB64(file){
  return new Promise(res=>{
    var r = new FileReader();
    r.onload = e => res(e.target.result.split(',')[1]);
    r.readAsDataURL(file);
  });
}

function removeUploadedFile(idx){
  GA_UPLOADED_FILES.splice(idx,1);
  renderUploadedFiles();
}

function renderUploadedFiles(){
  var el = document.getElementById('ga-uploaded-list');
  if(!el) return;
  if(!GA_UPLOADED_FILES.length){ el.innerHTML=''; return; }
  var icons = {pdf:'📄',docx:'📝',doc:'📝',txt:'📃',xlsx:'📊',xls:'📊'};
  el.innerHTML = GA_UPLOADED_FILES.map((f,i)=>`
    <div class="uf-item">
      <span class="uf-ico">${icons[f.ext]||'📎'}</span>
      <span class="uf-name" title="${escHtml(f.name)}">${escHtml(f.name)}</span>
      <span class="uf-size">${(f.size/1024).toFixed(0)} KB</span>
      <button class="uf-del" onclick="removeUploadedFile(${i})" title="Xoá">✕</button>
    </div>`).join('');
}

// ─── TẢI GIÁO ÁN DOCX ────────────────────────────────────────────
async function downloadGiaoAnDocx(){
  if(blockDownloadIfDisabled()) return;
  if(!GA_CURRENT_TEXT){ toast('Chưa có giáo án để tải'); return; }
  var btn = document.getElementById('ga-dl-btn');
  btn.disabled = true;
  btn.innerHTML = '<div class="ga-spinner" style="width:14px;height:14px;border-color:rgba(255,255,255,.3);border-top-color:#fff"></div> Đang tạo...';
  try {
    var titleEl = document.getElementById('ga-res-title');
    var titleText = titleEl ? titleEl.innerText.replace(/^[\s\S]*?([A-ZÀÁÂÃÈÉÊÌÍÒÓÔÕÙÚĂĐƠƯYA-Z].*)/, '$1').trim() : 'Giao_an';
    var safeTitle = titleText.replace(/[\\/:*?"<>|]/g,'_').slice(0,60);
    var docxBytes = await buildDocxFromMarkdown(GA_CURRENT_TEXT, titleText);
    var blob = new Blob([docxBytes], {type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});
    var url = URL.createObjectURL(blob);
    var a = document.createElement('a');
    a.href = url; a.download = 'GiaoAn_' + safeTitle + '.docx';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(()=>URL.revokeObjectURL(url), 1500);
    toast('✅ Đã tải giáo án DOCX!');
  } catch(e) {
    toast('❌ Lỗi tạo DOCX: '+e.message);
    console.error(e);
  } finally {
    btn.disabled = false;
    btn.innerHTML = '<i class="ti ti-file-download" style="font-size:13px"></i> Tải DOCX';
  }
}

// ─── BUILD DOCX TỪ MARKDOWN (không cần thư viện ngoài) ───────────
async function buildDocxFromMarkdown(md, title){
  // Dùng Anthropic API để chuyển MD → HTML rồi đóng gói DOCX minimal
  // Thực ra ta tạo DOCX từ scratch bằng JSZip-style (viết thủ công ZIP)
  // Giải pháp đơn giản & không cần CDN: tạo DOCX bằng cách ghép XML
  var xml = mdToDocxXml(md, title);
  return buildDocxZip(xml);
}

function mdToDocxXml(md, title){
  var lines = md.split('\n');
  var body = '';
  var i = 0;
  while(i < lines.length){
    var line = lines[i];
    // Bảng
    if(line.startsWith('|')){
      var tblLines = [];
      while(i < lines.length && lines[i].startsWith('|')){ tblLines.push(lines[i]); i++; }
      body += buildTableXml(tblLines);
      continue;
    }
    // Tiêu đề
    if(line.startsWith('### ')){
      body += wPara(wRun(escXml(line.slice(4).replace(/\*\*/g,'')), {bold:true, size:24, color:'4A148C'}), {before:160,after:60});
      i++; continue;
    }
    if(line.startsWith('## ')){
      body += wPara(wRun(escXml(line.slice(3).replace(/\*\*/g,'')), {bold:true, size:28, color:'0D47A1'}), {before:200,after:80});
      i++; continue;
    }
    if(line.startsWith('# ')){
      body += wPara(wRun(escXml(line.slice(2).replace(/\*\*/g,'')), {bold:true, size:32, color:'1B5E20'}), {before:240,after:100});
      i++; continue;
    }
    // Dòng trống
    if(!line.trim()){ body += wPara('', {before:40,after:40}); i++; continue; }
    // Italic note
    if(/^\*[^*].*[^*]\*$/.test(line)){
      body += wPara(wRun(escXml(line.slice(1,-1)), {italic:true, color:'757575', size:20}), {before:40,after:40});
      i++; continue;
    }
    // **bold standalone**
    if(/^\*\*[^*]+\*\*$/.test(line.trim())){
      var inner = line.trim().slice(2,-2);
      body += wPara(wRun(escXml(inner), {bold:true, size:26, color:'2E4057'}), {before:120,after:60});
      i++; continue;
    }
    // Dòng thường có inline bold
    body += wPara(inlineToXml(line), {before:60,after:60});
    i++;
  }
  return body;
}

function inlineToXml(text){
  var result = '';
  var re = /\*\*([^*]+)\*\*/g;
  var last = 0, m;
  while((m=re.exec(text))!==null){
    if(m.index>last) result += wRun(escXml(text.slice(last,m.index)), {});
    result += wRun(escXml(m[1]), {bold:true});
    last = m.index+m[0].length;
  }
  if(last<text.length) result += wRun(escXml(text.slice(last)), {});
  return result || wRun(escXml(text), {});
}

function wRun(text, opts){
  var rPr = '';
  if(opts.bold) rPr += '<w:b/><w:bCs/>';
  if(opts.italic) rPr += '<w:i/><w:iCs/>';
  if(opts.color) rPr += '<w:color w:val="'+opts.color+'"/>';
  if(opts.size) rPr += '<w:sz w:val="'+opts.size+'"/><w:szCs w:val="'+opts.size+'"/>';
  return '<w:r>'+(rPr?'<w:rPr>'+rPr+'</w:rPr>':'')+'<w:t xml:space="preserve">'+text+'</w:t></w:r>';
}

function wPara(content, spacing){
  var sp = spacing ? '<w:spacing w:before="'+(spacing.before||0)+'" w:after="'+(spacing.after||0)+'"/>' : '';
  return '<w:p><w:pPr>'+sp+'</w:pPr>'+content+'</w:p>';
}

function buildTableXml(lines){
  var rows = lines.filter(l => !l.match(/^\|\s*[-:]+/));
  if(!rows.length) return '';
  var parseRow = l => l.replace(/^\||\|$/g,'').split('|').map(c=>c.trim());
  var headers = parseRow(rows[0]);
  var dataRows = rows.slice(1);
  var colW = Math.floor(8640/headers.length);
  var mkCell = (txt, isH) => {
    var fill = isH ? 'E8F5E9' : 'FFFFFF';
    var color = isH ? '1B5E20' : '212121';
    var bold = isH ? '<w:b/><w:bCs/>' : '';
    var shd = '<w:shd w:val="clear" w:color="auto" w:fill="'+fill+'"/>';
    return '<w:tc><w:tcPr><w:tcW w:w="'+colW+'" w:type="dxa"/><w:tcBorders><w:top w:val="single" w:sz="1" w:color="BDBDBD"/><w:bottom w:val="single" w:sz="1" w:color="BDBDBD"/><w:left w:val="single" w:sz="1" w:color="BDBDBD"/><w:right w:val="single" w:sz="1" w:color="BDBDBD"/></w:tcBorders>'+shd+'<w:tcMar><w:top w:w="60" w:type="dxa"/><w:bottom w:w="60" w:type="dxa"/><w:left w:w="80" w:type="dxa"/><w:right w:w="80" w:type="dxa"/></w:tcMar></w:tcPr><w:p><w:pPr><w:spacing w:before="20" w:after="20"/></w:pPr><w:r><w:rPr>'+bold+'<w:color w:val="'+color+'"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr><w:t xml:space="preserve">'+escXml(txt)+'</w:t></w:r></w:p></w:tc>';
  };
  var mkRow = (cells, isH) => '<w:tr>'+(isH?'<w:trPr><w:tblHeader/></w:trPr>':'')+cells.map(c=>mkCell(c,isH)).join('')+'</w:tr>';
  var colWidths = Array(headers.length).fill(colW);
  return '<w:tbl><w:tblPr><w:tblW w:w="8640" w:type="dxa"/><w:tblBorders><w:insideH w:val="single" w:sz="1" w:color="BDBDBD"/><w:insideV w:val="single" w:sz="1" w:color="BDBDBD"/></w:tblBorders></w:tblPr><w:tblGrid>'+colWidths.map(w=>'<w:gridCol w:w="'+w+'"/>').join('')+'</w:tblGrid>'+mkRow(headers,true)+dataRows.map(r=>mkRow(parseRow(r),false)).join('')+'</w:tbl><w:p><w:pPr><w:spacing w:before="80" w:after="80"/></w:pPr></w:p>';
}

function escXml(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&apos;'); }

async function buildDocxZip(bodyXml){
  // Tạo DOCX (ZIP) thủ công không cần thư viện ngoài
  var docXml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
    '<w:document xmlns:wpc="http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas" '+
    'xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '+
    'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'+
    '<w:body>'+bodyXml+
    '<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134"/></w:sectPr>'+
    '</w:body></w:document>';

  var stylesXml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
    '<w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'+
    '<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="22"/></w:rPr></w:rPrDefault></w:docDefaults>'+
    '</w:styles>';

  var relsXml = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+
    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'+
    '</Relationships>';

  var docRels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
    '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+
    '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'+
    '</Relationships>';

  var contentTypes = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'+
    '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'+
    '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'+
    '<Default Extension="xml" ContentType="application/xml"/>'+
    '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'+
    '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'+
    '</Types>';

  // Encode các file thành bytes
  var enc = new TextEncoder();
  var files = [
    { name:'[Content_Types].xml', data: enc.encode(contentTypes) },
    { name:'_rels/.rels',         data: enc.encode(docRels) },
    { name:'word/document.xml',   data: enc.encode(docXml) },
    { name:'word/styles.xml',     data: enc.encode(stylesXml) },
    { name:'word/_rels/document.xml.rels', data: enc.encode(relsXml) },
  ];

  return buildZip(files);
}

function buildZip(files){
  // Tạo ZIP binary thủ công (không nén, stored)
  var parts = [];
  var centralDir = [];
  var offset = 0;

  function u16(n){ var b=new Uint8Array(2); b[0]=n&0xff; b[1]=(n>>8)&0xff; return b; }
  function u32(n){ var b=new Uint8Array(4); b[0]=n&0xff; b[1]=(n>>8)&0xff; b[2]=(n>>16)&0xff; b[3]=(n>>24)&0xff; return b; }
  function concat(...arrs){ var len=arrs.reduce((a,b)=>a+b.length,0); var out=new Uint8Array(len); var p=0; arrs.forEach(a=>{out.set(a,p);p+=a.length;}); return out; }
  function crc32(data){
    var table=[]; for(var i=0;i<256;i++){var c=i;for(var j=0;j<8;j++)c=c&1?0xEDB88320^(c>>>1):c>>>1;table.push(c);}
    var crc=0xFFFFFFFF;
    for(var k=0;k<data.length;k++)crc=table[(crc^data[k])&0xff]^(crc>>>8);
    return (crc^0xFFFFFFFF)>>>0;
  }

  var enc2 = new TextEncoder();
  for(var f of files){
    var nameBytes = enc2.encode(f.name);
    var crc = crc32(f.data);
    var localHdr = concat(
      new Uint8Array([0x50,0x4B,0x03,0x04]), // sig
      u16(20), u16(0), u16(0),              // version, flag, method(stored)
      u16(0), u16(0),                        // mod time, date
      u32(crc), u32(f.data.length), u32(f.data.length),
      u16(nameBytes.length), u16(0),
      nameBytes
    );
    parts.push(localHdr, f.data);
    centralDir.push(concat(
      new Uint8Array([0x50,0x4B,0x01,0x02]),
      u16(20), u16(20), u16(0), u16(0),
      u16(0), u16(0), u16(0),
      u32(crc), u32(f.data.length), u32(f.data.length),
      u16(nameBytes.length), u16(0), u16(0), u16(0), u16(0), u32(0),
      u32(offset),
      nameBytes
    ));
    offset += localHdr.length + f.data.length;
  }

  var cdData = concat(...centralDir);
  var eocd = concat(
    new Uint8Array([0x50,0x4B,0x05,0x06]),
    u16(0), u16(0),
    u16(files.length), u16(files.length),
    u32(cdData.length), u32(offset),
    u16(0)
  );
  return concat(...parts, cdData, eocd);
}

// ─── GIÁO ÁN AI ──────────────────────────────────────────────────────────────
var GA_HISTORY = [];
var GA_CURRENT_TEXT = '';
var GA_MESSAGES = [];   // conversation history for follow-up

function buildGiaoAnPrompt(){
  var age   = document.getElementById('ga-age').value;
  var mon   = document.getElementById('ga-mon').value;
  var chude = document.getElementById('ga-chude').value;
  var ten   = document.getElementById('ga-tenbai').value.trim() || mon + ' – ' + chude;
  var tg    = document.getElementById('ga-tg').value;
  var note  = document.getElementById('ga-note').value.trim();

  var nls = [];
  document.querySelectorAll('#ga-nl-pick input:checked').forEach(cb => nls.push(cb.value));

  var tks = [];
  document.querySelectorAll('#ga-tk-pick input:checked').forEach(cb => tks.push(cb.value));

  var prompt = `Bạn là chuyên gia soạn thảo giáo án Giáo dục Mầm non theo Chương trình thí điểm 2026 (QĐ 388/QĐ-BGDĐT ngày 12/02/2026).

Hãy soạn một giáo án chi tiết, đầy đủ với các thông tin sau:

**THÔNG TIN CƠ BẢN:**
- Độ tuổi: ${age}
- Môn / Lĩnh vực phát triển: ${mon}
- Chủ đề: ${chude}
- Tên hoạt động: ${ten}
- Thời gian: ${tg} phút
- Năng lực trọng tâm: ${nls.join(', ') || 'Giao tiếp, Khám phá KH'}
- Tích hợp: ${tks.length ? tks.join(', ') : 'không có'}
${note ? '- Yêu cầu đặc biệt: ' + note : ''}

**YÊU CẦU QUAN TRỌNG – CẦN BÁM SÁT CT THÍ ĐIỂM 2026:**

1. **Mục tiêu:** Viết theo YCCĐ (Yêu cầu cần đạt) CÓ THỂ QUAN SÁT ĐƯỢC – KHÔNG viết theo KT/KN/TĐ cũ. Mỗi YCCĐ phải có mã (VD: NT2.1, TX5.2, NN2.2) và ghi rõ mức I/H/V mong đợi.

2. **Chuẩn bị môi trường:** Không dùng từ "Đồ dùng của cô / của trẻ". Thay bằng "Chuẩn bị môi trường học tập".

3. **Tiến trình 4 GIAI ĐOẠN** (KHÔNG dùng cấu trúc cũ "Ổn định – Nội dung – Kết thúc"):
   - **GĐ1 – Gây hứng thú** (3-5 phút): Tình huống/câu hỏi/vật bí ẩn kích thích tò mò. KHÔNG giảng bài ngay.
   - **GĐ2 – Khám phá** (10-15 phút): Trẻ TỰ khám phá theo nhóm nhỏ (3-5 trẻ). GV KHÔNG làm mẫu trước. Đặt câu hỏi mở.
   - **GĐ3 – Chia sẻ & Thực hành** (8-12 phút): Trẻ chia sẻ kết quả. GV ghi chép, hỏi thêm. Tạo sản phẩm/giải quyết vấn đề.
   - **GĐ4 – Mở rộng** (3-5 phút): Kết nối với cuộc sống thực. Gợi ý tiếp tục ở nhà/góc chơi. KHÔNG tổng kết theo kiểu giảng bài.

4. **Câu hỏi gợi mở:** Ít nhất 5 câu hỏi mở theo kiểu Socratic (KHÔNG hỏi câu đóng có 1 đáp án đúng). VD: "Con nghĩ tại sao...?", "Nếu...thì điều gì xảy ra?", "Con có thể làm cách nào khác không?"

5. **Vai trò giáo viên:** Nêu rõ "QUAN SÁT + GHI CHÉP là chính. KHÔNG làm mẫu trước. KHÔNG sửa sản phẩm của trẻ."

6. **Minh chứng đánh giá:** Cụ thể: ảnh/video làm gì, sản phẩm cụ thể, câu nói nguyên văn, mức NL I/H/V tương ứng.

7. **Điều chỉnh:** Ghi rõ cho (a) trẻ gặp khó khăn, (b) trẻ nổi trội, (c) trẻ hoà nhập (nếu có).

8. **So sánh:** Thêm 1 bảng ngắn so sánh CT cũ → CT mới 2026 cho bài này.

9. **Hòa nhập (MD6):** Nếu có "trẻ hoà nhập", "trẻ đặc biệt", "autism" hay yêu cầu tương tự trong ghi chú:
   - Thêm mục **"Điều chỉnh cho trẻ hòa nhập"** sau GĐ4
   - Ghi rõ: điều chỉnh MỤC TIÊU (đơn giản hơn), HỌC LIỆU (trực quan hơn), THỜI GIAN (linh hoạt)
   - KHÔNG yêu cầu trẻ hòa nhập đạt cùng mức với lớp
   - Đề xuất 1 mục tiêu riêng (IEP mini) phù hợp đặc điểm trẻ
   - Nguyên tắc vàng: So sánh trẻ hòa nhập với CHÍNH trẻ ở giai đoạn trước

**ĐỊNH DẠNG ĐẦU RA:**
Dùng Markdown rõ ràng với các heading ##, ###. Dùng bảng cho phần so sánh. Viết đầy đủ, chi tiết, thực tế – có thể dùng ngay để dạy học. Ngôn ngữ tiếng Việt, chuyên nghiệp nhưng thân thiện.`;

  // Thêm nội dung file txt đã upload (nếu có)
  var uploadCtx = '';
  GA_UPLOADED_FILES.forEach(function(f){
    if(f.text) uploadCtx += '\n\n--- Nội dung file: ' + f.name + ' ---\n' + f.text.slice(0,3000);
  });
  if(uploadCtx) prompt += '\n\n**TÀI LIỆU THAM KHẢO (GV ĐỀ NGHỊ TÍCH HỢP):**' + uploadCtx;
  
  return { age, mon, chude, ten, tg, nls, tks, note, prompt };
}

// ─── TRỢ LÝ AI: các chức năng mở rộng (gợi ý hoạt động / tư vấn tình huống /
// nhận xét trẻ) — dùng chung endpoint /api/ai/messages đã có sẵn cho giáo án.
function setAiTab(el, tab){
  document.querySelectorAll('#ai-tabs .tab').forEach(function(t){ t.classList.remove('on'); });
  if(el) el.classList.add('on');
  ['giaoan','hoatdong','tinhhuong','nhanxet'].forEach(function(t){
    var sec = document.getElementById('ai-tab-' + t);
    if(sec) sec.style.display = (t === tab) ? 'block' : 'none';
  });
}

async function callAiAssistant(system, userText, maxTokens){
  var resp = await fetch(API_BASE + '/api/ai/messages', {
    method: 'POST',
    headers: Object.assign({'Content-Type': 'application/json'}, authHeaders()),
    body: JSON.stringify({
      model: 'claude-sonnet-5',
      max_tokens: maxTokens || 1500,
      system: system,
      messages: [{role: 'user', content: userText}]
    })
  });
  var data = await resp.json();
  if(!resp.ok){
    if(resp.status === 412){ openAiSettings(); throw new Error('Chưa cấu hình API key AI. Vui lòng nhập rồi thử lại.'); }
    throw new Error(data.detail || (data.error && data.error.message) || 'Lỗi API ' + resp.status);
  }
  return data.content.map(function(b){ return b.type === 'text' ? b.text : ''; }).join('');
}

