async function generateGiaoAn(){
  var info = buildGiaoAnPrompt();
  if(!info.ten && !document.getElementById('ga-tenbai').value.trim()){
    // auto-fill tenbai
  }

  var btn = document.getElementById('ga-btn');
  var loading = document.getElementById('ga-loading');
  var statusEl = document.getElementById('ga-status');
  btn.disabled = true;
  loading.style.display = 'flex';
  statusEl.textContent = 'Đang kết nối AI...';
  document.getElementById('ga-result').style.display = 'none';

  // Xây dựng content có thể đính kèm file PDF/image
  var userContent = [];
  GA_UPLOADED_FILES.forEach(function(f){
    if(f.ext === 'pdf'){
      userContent.push({ type:'document', source:{ type:'base64', media_type:'application/pdf', data:f.b64 } });
    }
  });
  userContent.push({ type:'text', text: info.prompt });
  GA_MESSAGES = [{ role:'user', content: userContent.length === 1 ? info.prompt : userContent }];

  try {
    statusEl.textContent = 'AI đang soạn giáo án ⏳';
    var resp = await fetch(API_BASE+'/api/ai/messages',{
      method:'POST',
      headers:Object.assign({'Content-Type':'application/json'},authHeaders()),
      body: JSON.stringify({
        model:'claude-sonnet-5',
        max_tokens:3000,
        system:'Bạn là chuyên gia soạn giáo án Giáo dục Mầm non Việt Nam, thành thạo Chương trình thí điểm 2026 theo QĐ 388. Luôn trả lời bằng tiếng Việt. Soạn giáo án chuyên nghiệp, chi tiết, thực tế, có thể áp dụng ngay. Dùng Markdown với heading rõ ràng.',
        messages: GA_MESSAGES
      })
    });
    var data = await resp.json();
    if(!resp.ok){
      if(resp.status === 412){ openAiSettings(); throw new Error('Chưa cấu hình API key AI. Vui lòng nhập rồi thử lại.'); }
      throw new Error(data.detail || data.error?.message || 'API error '+resp.status);
    }
    var text = data.content.map(b=>b.type==='text'?b.text:'').join('');
    GA_CURRENT_TEXT = text;
    GA_MESSAGES.push({role:'assistant', content: text});

    // Render
    var titleEl = document.getElementById('ga-res-title');
    titleEl.innerHTML = '<i class="ti ti-file-text"></i>' + info.ten + ' – ' + info.age;
    document.getElementById('ga-res-body').innerHTML = '<div class="ga-res-body">' + mdToHtml(text) + '</div>';
    document.getElementById('ga-result').style.display = 'block';
    document.getElementById('ga-result').scrollIntoView({behavior:'smooth',block:'start'});
    document.getElementById('ga-chat-history').style.display = 'none';
    document.getElementById('ga-chat-history').innerHTML = '';

    // Save history
    GA_HISTORY.unshift({
      id: Date.now(),
      title: info.ten,
      age: info.age,
      mon: info.mon,
      chude: info.chude,
      text: text,
      time: new Date().toLocaleString('vi-VN'),
      messages: JSON.parse(JSON.stringify(GA_MESSAGES))
    });
    renderGaHistory();
    statusEl.textContent = '✅ Giáo án đã sẵn sàng!';
    toast('✨ Đã tạo giáo án: ' + info.ten);
  } catch(err){
    statusEl.textContent = '❌ Lỗi: ' + err.message;
    document.getElementById('ga-result').style.display = 'none';
    toast('❌ Lỗi kết nối AI – ' + err.message);
  } finally {
    btn.disabled = false;
    loading.style.display = 'none';
  }
}

async function askFollowup(question){
  await sendFollowupMsg(question);
}

async function sendFollowup(){
  var inp = document.getElementById('ga-ask-inp');
  var q = inp.value.trim();
  if(!q) return;
  inp.value = '';
  await sendFollowupMsg(q);
}

async function sendFollowupMsg(q){
  if(!GA_MESSAGES.length){toast('Hãy tạo giáo án trước!');return;}
  var hist = document.getElementById('ga-chat-history');
  hist.style.display = 'block';
  hist.innerHTML += '<div class="chat-msg chat-user"><div class="bubble">' + escHtml(q) + '</div></div>';
  hist.innerHTML += '<div class="chat-msg chat-ai" id="chat-typing"><div class="bubble"><div class="ga-spinner" style="display:inline-block;width:14px;height:14px;margin-right:5px;vertical-align:middle"></div>Đang trả lời...</div></div>';
  hist.scrollTop = hist.scrollHeight;
  document.querySelectorAll('.ga-q-btn').forEach(b=>b.disabled=true);

  GA_MESSAGES.push({role:'user', content: q});
  try {
    var resp = await fetch(API_BASE+'/api/ai/messages',{
      method:'POST',
      headers:Object.assign({'Content-Type':'application/json'},authHeaders()),
      body:JSON.stringify({
        model:'claude-sonnet-5',
        max_tokens:1500,
        system:'Bạn là chuyên gia soạn giáo án GDMN theo CT thí điểm 2026 (QĐ 388). Trả lời ngắn gọn, trực tiếp, thực tế. Tiếng Việt. Dùng Markdown nhẹ.',
        messages: GA_MESSAGES
      })
    });
    var data = await resp.json();
    if(!resp.ok){
      if(resp.status === 412) openAiSettings();
      throw new Error(data.detail || data.error?.message || 'Lỗi API');
    }
    var ans = data.content.map(b=>b.type==='text'?b.text:'').join('');
    GA_MESSAGES.push({role:'assistant',content:ans});
    var typing = document.getElementById('chat-typing');
    if(typing) typing.outerHTML = '<div class="chat-msg chat-ai"><div class="bubble">' + mdToHtml(ans) + '</div></div>';
    hist.scrollTop = hist.scrollHeight;
  } catch(e){
    var typing = document.getElementById('chat-typing');
    if(typing) typing.outerHTML = '<div class="chat-msg chat-ai"><div class="bubble" style="color:var(--rd)">❌ Lỗi: ' + escHtml(e.message) + '</div></div>';
  } finally {
    document.querySelectorAll('.ga-q-btn').forEach(b=>b.disabled=false);
  }
}

