function recordsFilterBar(items){
  return '<div class="records-filter">'+items.map(function(x){return '<label><span>'+x+'</span><select><option>Dữ liệu minh họa</option></select></label>';}).join('')+'</div>';
}
function evidenceFormatSize(size){
  if(!size && size!==0) return 'Dung lượng minh họa';
  if(size<1024) return size+' B';
  if(size<1024*1024) return Math.round(size/1024)+' KB';
  return (size/1024/1024).toFixed(1)+' MB';
}
function evidenceFileIcon(fileName,type){
  var n=(fileName||'').toLowerCase();
  if(type==='image'||/\.(jpg|jpeg|png|webp)$/.test(n)) return 'ti-photo';
  if(type==='video'||/\.(mp4|mov)$/.test(n)) return 'ti-video';
  if(/\.pdf$/.test(n)) return 'ti-file-type-pdf';
  if(/\.docx$/.test(n)) return 'ti-file-type-docx';
  if(/\.xlsx$/.test(n)) return 'ti-file-spreadsheet';
  return 'ti-file-text';
}
function renderEvidencePreviewList(context){
  var list=(SELECTED_EVIDENCE_FILES[context]||[]).concat(DEMO_EVIDENCE_FILES.slice(0,context==='dashboard'?2:3));
  return '<div class="evidence-list">'+list.map(function(f){
    var isSelected=String(f.id).indexOf('local-')===0;
    var thumb=f.previewUrl?'<img src="'+f.previewUrl+'" alt="preview" />':'<i class="ti '+evidenceFileIcon(f.fileName,f.type)+'"></i>';
    return '<div class="evidence-item"><div class="evidence-thumb">'+thumb+'</div><div class="evidence-meta"><b>'+f.fileName+'</b><span>'+f.fileType+' · '+(f.sizeText||'Tệp minh chứng minh họa')+'</span><span>'+f.field+' · '+f.yccd+'</span><span>'+f.context+'</span></div><div class="evidence-item-actions">'+(f.previewUrl?'<button onclick="openEvidencePreview(\''+f.previewUrl+'\')">Xem trước</button>':'<button onclick="toast(\'Demo: xem file minh chứng\')">Xem trước</button>')+(isSelected?'<button onclick="removeEvidenceFile(\''+context+'\',\''+f.id+'\')">Xóa</button>':'')+'</div></div>';
  }).join('')+'</div>';
}
function renderEvidenceUploadBox(context,title,featured){
  var inputId='evidence-input-'+context;
  return '<section class="evidence-box '+(featured?'featured':'')+'"><div class="evidence-head"><div><h3>'+title+'</h3><p>Tệp minh chứng minh họa – chưa lưu vào hệ thống. Sau này sẽ lưu vào thư mục minh chứng khi kết nối backend.</p></div><button onclick="openEvidenceModal(\''+context+'\')">'+(featured?'+ Thêm minh chứng vào Portfolio':'Thêm ảnh/video/file')+'</button></div><div class="evidence-drop" onclick="document.getElementById(\''+inputId+'\').click()"><i class="ti ti-cloud-upload"></i><b>Kéo thả file hoặc bấm để chọn file</b><span>Ảnh .jpg/.jpeg/.png/.webp · Video .mp4/.mov · Tài liệu .pdf/.docx/.xlsx · Ghi chú .txt</span><small>Khuyến nghị minh chứng ngắn gọn, rõ bối cảnh, không dùng để so sánh trẻ.</small></div><input id="'+inputId+'" type="file" multiple accept=".jpg,.jpeg,.png,.webp,.mp4,.mov,.pdf,.docx,.xlsx,.txt" onchange="handleEvidenceFileSelect(\''+context+'\',this)" style="display:none" /><div class="evidence-fields"><label>Bối cảnh minh chứng<input placeholder="Dữ liệu minh họa" /></label><label>Mã/YCCĐ liên quan<input placeholder="Chờ import dữ liệu từ Excel" /></label><label>Phẩm chất/năng lực liên quan<input placeholder="Giao tiếp, hợp tác, tự lực..." /></label><label>Nhận xét ngắn của giáo viên<input placeholder="Dữ liệu minh họa" /></label><label>Hướng hỗ trợ tiếp theo<input placeholder="Điều chỉnh/hỗ trợ phù hợp" /></label></div><div class="note warn"><i class="ti ti-shield-lock"></i><div>Minh chứng của trẻ cần được quản lý an toàn, chỉ dùng cho mục đích giáo dục và phối hợp với cha mẹ.</div></div>'+renderEvidencePreviewList(context)+'</section>';
}
function refreshRecordsPage(){
  if(CUR_PAGE==='observation-log') renderObservationJournal();
  if(CUR_PAGE==='child-profile') renderChildProfile();
  if(CUR_PAGE==='portfolio') renderPortfolio();
  if(CUR_PAGE==='parent-sheet') renderParentCommunication();
  if(CUR_PAGE==='dashboard') renderDashboard();
}
function handleEvidenceFileSelect(context,input){
  try{
    var files=Array.prototype.slice.call(input.files||[]);
    if(!SELECTED_EVIDENCE_FILES[context]) SELECTED_EVIDENCE_FILES[context]=[];
    files.forEach(function(file){
      var isImage=/^image\//.test(file.type);
      var item={id:'local-'+Date.now()+'-'+Math.random().toString(16).slice(2),childName:'Trẻ minh họa',date:new Date().toLocaleDateString('vi-VN'),type:isImage?'image':(/^video\//.test(file.type)?'video':'file'),fileName:file.name,fileType:isImage?'Ảnh':(/^video\//.test(file.type)?'Video':'Tài liệu'),field:'Dữ liệu minh họa',yccd:'Chờ import dữ liệu từ Excel',competency:'Dữ liệu minh họa',context:'Minh chứng giáo viên vừa chọn',teacherNote:'Tệp minh chứng minh họa – chưa lưu vào hệ thống.',nextSupport:'Sẽ cập nhật khi kết nối backend.',sizeText:evidenceFormatSize(file.size)};
      if(isImage && window.URL && URL.createObjectURL) item.previewUrl=URL.createObjectURL(file);
      SELECTED_EVIDENCE_FILES[context].push(item);
    });
    input.value='';
    refreshRecordsPage();
    toast('Demo: đã thêm tệp vào danh sách xem trước local.');
  }catch(err){ if(window.console&&console.error) console.error(err); toast('Không thể đọc file trong trình duyệt hiện tại.'); }
}
function removeEvidenceFile(context,id){
  try{SELECTED_EVIDENCE_FILES[context]=(SELECTED_EVIDENCE_FILES[context]||[]).filter(function(f){return f.id!==id;});refreshRecordsPage();}catch(err){toast('Demo: chưa thể xóa tệp.');}
}
function openEvidencePreview(url){
  try{window.open(url,'_blank');}catch(err){toast('Trình duyệt chưa cho phép xem trước.');}
}
function openEvidenceModal(context){
  var old=document.getElementById('evidence-modal-bg'); if(old) old.remove();
  var div=document.createElement('div'); div.id='evidence-modal-bg'; div.className='evidence-modal-bg';
  div.innerHTML='<div class="evidence-modal"><button class="evidence-close" onclick="closeEvidenceModal()">×</button><h3>Thêm minh chứng demo</h3><p>Tệp minh chứng minh họa – chưa lưu vào hệ thống. Sau này sẽ lưu vào thư mục minh chứng khi kết nối backend.</p>'+renderEvidenceUploadBox(context+'-modal','Chọn file ảnh/video/tài liệu',false)+'<div class="evidence-fields"><label>Tên minh chứng<input placeholder="Dữ liệu minh họa" /></label><label>Ngày ghi nhận<input type="date" /></label><label>Hoạt động/bối cảnh<input placeholder="Dữ liệu minh họa" /></label><label>Lĩnh vực<input placeholder="Dữ liệu minh họa" /></label><label>Câu nói/hành động của trẻ<textarea placeholder="Dữ liệu minh họa"></textarea></label><label>Hướng hỗ trợ/mở rộng<textarea placeholder="Dữ liệu minh họa"></textarea></label></div></div>';
  document.body.appendChild(div);
}
