  var stats=[['Tổng số trẻ','28'],['Số lượt quan sát','96'],['Số minh chứng đã tải lên','142'],['Trẻ có portfolio','24'],['Minh chứng chờ nhận xét','9'],['Minh chứng đã chia sẻ cha mẹ','18']].map(function(s){return '<div class="records-stat"><b>'+s[1]+'</b><span>'+s[0]+'</span></div>';}).join('');
