    var statNames=[['Nhóm tuổi','age_groups'],['Lĩnh vực','domains'],['Phẩm chất','qualities'],['Năng lực','competencies'],['Mã/YCCĐ','yccd'],['Kế hoạch năm','year_plans'],['Hoạt động','activities'],['Rubric','rubrics'],['Trẻ','children'],['Quan sát','observations'],['Minh chứng','portfolio'],['Hồ sơ','assessments']];
