  datasets: [
    {id:'nursery', title:'Bộ Nhà trẻ 12–36 tháng', icon:'ti-baby-carriage', desc:'Phù hợp với chăm sóc, nuôi dưỡng, sinh hoạt hằng ngày, chơi, giao tiếp, vận động, cảm xúc và khám phá giác quan.', ages:['12–24 tháng','24–36 tháng']},
    {id:'kindergarten', title:'Bộ Mẫu giáo 3–6 tuổi', icon:'ti-school', desc:'Phù hợp với phát triển phẩm chất, năng lực qua chơi, trải nghiệm, hợp tác, khám phá, biểu đạt và giải quyết vấn đề.', ages:['3–4 tuổi','4–5 tuổi','5–6 tuổi']}
  ],
