function renderPlanPreview(){
  if(!selectedDataset || !selectedAge || !selectedPlanType || !selectedDataItems.length){
    return '<h3 class="planwiz-title">Bước 5. Xem trước bản nháp kế hoạch</h3><div class="planwiz-empty">Vui lòng hoàn thiện các bước trước khi xem bản nháp.</div>'+renderPlanPreviewActions();
  }
  if(selectedPlanType==='year') return renderYearPlanPreview();
  if(selectedPlanType==='month') return renderMonthThemePlanPreview();
  if(selectedPlanType==='week') return renderWeekPlanPreview();
  if(selectedPlanType==='day') return renderDayPlanPreview();
  if(selectedPlanType==='activity') return renderActivityPlanPreview();
  return '<h3 class="planwiz-title">Bước 5. Xem trước bản nháp kế hoạch</h3><div class="planwiz-empty">Vui lòng hoàn thiện các bước trước khi xem bản nháp.</div>'+renderPlanPreviewActions();
}
function copyPlanDraft(){
  try{
    var body=document.getElementById('planwiz-body');
    var text=body?body.innerText:'';
    if(navigator.clipboard && text){navigator.clipboard.writeText(text).then(function(){toast('Đã sao chép bản nháp demo.');}).catch(function(){toast('Trình duyệt chưa cho phép sao chép tự động.');});return;}
    toast('Trình duyệt chưa cho phép sao chép tự động.');
  }catch(err){toast('Chưa thể sao chép bản nháp trong trình duyệt hiện tại.');}
}
function planWizardNext(){
  try{
    if(currentWizardStep===1 && !selectedDataset){toast('Vui lòng chọn bộ tài liệu trước.');return;}
    if(currentWizardStep===2 && !selectedAge){toast('Vui lòng chọn độ tuổi.');return;}
    if(currentWizardStep===3 && !selectedPlanType){toast('Vui lòng chọn loại kế hoạch.');return;}
    if(currentWizardStep===4 && !selectedDataItems.length){toast('Vui lòng chọn ít nhất một nhóm dữ liệu.');return;}
    if(currentWizardStep<5){currentWizardStep++;renderPlanWizard();return;}
    toast('Demo: bản nháp kế hoạch đã sẵn sàng để xem trước.');
  }catch(err){renderPlanWizardError(err);}
}function planWizardPrev(){try{if(currentWizardStep>1){currentWizardStep--;renderPlanWizard();}else{toast('Đang ở bước đầu tiên.');}}catch(err){renderPlanWizardError(err);}}
function selectPlanDataset(id){try{selectedDataset=id;selectedAge='';renderPlanWizard();}catch(err){renderPlanWizardError(err);}}
function selectPlanAge(age){try{selectedAge=age;renderPlanWizard();}catch(err){renderPlanWizardError(err);}}
function selectPlanType(type){try{selectedPlanType=type;renderPlanWizard();}catch(err){renderPlanWizardError(err);}}
function togglePlanDataItem(item){try{var i=selectedDataItems.indexOf(item);if(i>=0)selectedDataItems.splice(i,1);else selectedDataItems.push(item);renderPlanWizard();}catch(err){renderPlanWizardError(err);}}
function resetPlanWizard(){try{currentWizardStep=1;selectedDataset='';selectedAge='';selectedPlanType='';selectedDataItems=[];renderPlanWizard();}catch(err){renderPlanWizardError(err);}}
window.openEvidenceModal=openEvidenceModal;
window.closeEvidenceModal=closeEvidenceModal;
